 static void integrations(WorkflowSupport h)throws Exception{
  String record=h.add("incident").get("sys_id").toString();try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.environment)){
   var source=new AtomicReference<>(map("record_id",record,"version","one","values",map("short_description","External approved value")));var authorization=new AtomicReference<String>();provider.server.createContext("/record",exchange->{byte[] bytes=JSON.writeValueAsBytes(source.get());exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);exchange.close();});provider.server.createContext("/oauth/token",exchange->{authorization.set(exchange.getRequestHeaders().getFirst("Authorization"));byte[] bytes=JSON.writeValueAsBytes(map("access_token","refreshed-synthetic-token","token_type","Bearer","expires_in",3600));exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);exchange.close();});
   var oauth=map("operation","oauth","alias",provider.alias,"revision",0,"connector_revision",1,"token_path","/oauth/token","client_id","synthetic:client +","client_secret"," synthetic-secret & ","scope","records:read");send(h,"integrations","global",oauth);assertFalse(JSON.writeValueAsString(page(h,"integrations","global")).contains("synthetic-secret"));assertFalse(JSON.writeValueAsString(doc(h,"oauth",provider.alias)).contains("synthetic-secret"));send(h,"integrations","global",map("operation","refresh","alias",provider.alias,"revision",1));assertEquals("Basic "+Base64.getEncoder().encodeToString("synthetic%3Aclient+%2B:+synthetic-secret+%26+".getBytes()),authorization.get());assertTrue(((Number)object(doc(h,"oauth",provider.alias).get("definition")).get("expires_at")).longValue()>System.currentTimeMillis());
   var review=map("operation","review_pull","alias",provider.alias,"path","/record","table","incident","record_id",record,"fields",List.of("short_description"));var out=object(send(h,"integrations","global",review).get("outcome"));assertEquals(false,out.get("conflict"));var apply=new LinkedHashMap<>(review);apply.putAll(map("operation","apply_pull","proof",out.get("proof"),"confirm",true));result(h.json("PATCH","/api/now/table/incident/"+record,map("description","Concurrent change"),auth("admin")));bad(h,"integrations","global",apply,409);out=object(send(h,"integrations","global",review).get("outcome"));apply.put("proof",out.get("proof"));send(h,"integrations","global",apply);assertEquals("External approved value",EmployeeCasesAcceptance.get(h,"/api/now/table/incident/"+record,"admin").get("short_description"));assertEquals(false,object(send(h,"integrations","global",review).get("outcome")).get("conflict"));source.set(map("record_id",record,"version","two","values",map("short_description","Remote change")));result(h.json("PATCH","/api/now/table/incident/"+record,map("short_description","Local change"),auth("admin")));assertEquals(true,object(send(h,"integrations","global",review).get("outcome")).get("conflict"));
   provider.settings.put("CONNECTOR_WRITES_ENABLED","true");var action=ConnectorActionsAcceptance.create(h,provider.alias);String actionId=action;var push=map("operation","review_push","table","incident","record_id",record,"action_id",actionId,"mapping",map("title","short_description"),"key",id());var preview=object(send(h,"integrations","global",push).get("outcome"));push.putAll(map("operation","queue_push","proof",preview.get("proof"),"state",preview.get("state"),"preview_token",preview.get("preview_token"),"confirm",true));send(h,"integrations","global",push);assertEquals(1,objects(data(h,"integrations","global").get("synchronizations")).size());
  }
 }
 static Map<String,Object> planState(WorkflowSupport h,String key)throws Exception{return object(doc(h,"agent-plan",key).get("definition"));}
 static void agents(WorkflowSupport h)throws Exception{
  h.account("NativeAgent","agent");String delegate=uid(h,"NativeAgent"),first=h.add("incident").get("sys_id").toString(),second=h.add("problem").get("sys_id").toString();try(var db=h.store.open()){db.update("UPDATE os_user SET api_only=1 WHERE user_id=?",delegate);db.connection.commit();}
  var targets=List.of(map("table","incident","record_id",first,"fields",List.of("short_description")),map("table","problem","record_id",second,"fields",List.of("short_description")));send(h,"agents","global",map("operation","grant","delegate_id",delegate,"revision",0,"active",true,"targets",targets));String key=id();var review=map("operation","review","key",key,"delegate_id",delegate,"grant_revision",1,"steps",List.of(map("table","incident","record_id",first,"patch",map("short_description","Delegated update one")),map("table","problem","record_id",second,"patch",map("short_description","Delegated update two"))));String original=EmployeeCasesAcceptance.get(h,"/api/now/table/incident/"+first,"admin").get("short_description").toString();send(h,"agents","global",review);assertEquals(original,EmployeeCasesAcceptance.get(h,"/api/now/table/incident/"+first,"admin").get("short_description"));bad(h,"agents","global",map("operation","start","key",key,"revision",1,"confirm",true),400);assertFalse(AgentPlans.runOne(h.store));
  try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.environment)){provider.settings.put("AI_AGENT_EXECUTION_ENABLED","true");send(h,"agents","global",map("operation","start","key",key,"revision",1,"confirm",true));new Store(h.environment);assertTrue(AgentPlans.runOne(h.store));assertEquals("Delegated update one",EmployeeCasesAcceptance.get(h,"/api/now/table/incident/"+first,"admin").get("short_description"));assertEquals("queued",planState(h,key).get("state"));assertEquals(delegate,objects(planState(h,key).get("receipts")).getFirst().get("executed_by"));send(h,"agents","global",map("operation","stop","key",key,"revision",3,"reason","Operator stopped remaining effects"));assertFalse(AgentPlans.runOne(h.store));assertNotEquals("Delegated update two",EmployeeCasesAcceptance.get(h,"/api/now/table/problem/"+second,"admin").get("short_description"));
   String complete=id();review.put("key",complete);send(h,"agents","global",review);send(h,"agents","global",map("operation","start","key",complete,"revision",1,"confirm",true));assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));assertTrue(AgentPlans.runOne(h.store));assertEquals("completed",planState(h,complete).get("state"));assertEquals(2,objects(planState(h,complete).get("receipts")).size());
   String revoked=id();review.put("key",revoked);send(h,"agents","global",review);send(h,"agents","global",map("operation","start","key",revoked,"revision",1,"confirm",true));send(h,"agents","global",map("operation","revoke","delegate_id",delegate,"revision",1));assertTrue(AgentPlans.runOne(h.store));assertEquals("failed",planState(h,revoked).get("state"));assertTrue(objects(planState(h,revoked).get("receipts")).isEmpty());
  }
 }
